TLM.f("Sancti/09-08",{"officium":"Nativitate Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=Nativitate"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Fámulis tuis, quǽsumus, Dómine, cœléstis grátiæ munus impertíre: ut, quibus beátæ Vírginis partus éxstitit salútis exórdium; Nativitátis ejus votíva sollémnitas pacis tríbuat increméntum."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"rubric","la":"Prov 8:22-35"},{"k":"text","la":"Dóminus possedit me in inítio viárum suárum, ántequam quidquam fáceret a princípio. Ab ætérno ordináta sum, et ex antíquis, ántequam terra fíeret. Nondum erant abýssi, et ego jam concépta eram: necdum fontes aquárum erúperant: necdum montes gravi mole constíterant: ante colles ego parturiébar: adhuc terram non fécerat et flúmina et cárdines orbis terræ. Quando præparábat cœlos, áderam: quando certa lege et gyro vallábat abýssos: quando æthera firmábat sursum et librábat fontes aquárum: quando circúmdabat mari términum suum et legem ponébat aquis, ne transírent fines suos: quando appendébat fundaménta terræ. Cum eo eram cuncta compónens: et delectábar per síngulos dies, ludens coram eo omni témpore: ludens in orbe terrárum: et delíciæ meæ esse cum filiis hóminum. Nunc ergo, filii, audíte me: Beáti, qui custódiunt vias meas. Audíte disciplínam, et estóte sapiéntes, et nolíte abjícere eam. Beátus homo, qui audit me et qui vígilat ad fores meas cotídie, et obsérvat ad postes óstii mei. Qui me invénerit, invéniet vitam et háuriet salútem a Dómino."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Felix es, sacra Virgo María, et omni laude digníssima: quia ex te ortus est sol justítiæ, Christus, Deus noster. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Initium ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 1:1-16"},{"k":"text","la":"Liber generatiónis Jesu Christi, fílii David, fílii Abraham. Abraham génuit Isaac. Isaac autem génuit Jacob. Jacob autem génuit Judam et fratres ejus. Judas autem génuit Phares et Zaram de Thamar. Phares autem génuit Esron. Esron autem génuit Aram. Aram autem génuit Amínadab. Amínadab autem génuit Naásson. Naásson autem génuit Salmon. Salmon autem génuit Booz de Rahab. Booz autem génuit Obed ex Ruth. Obed autem génuit Jesse. Jesse autem génuit David regem. David autem rex génuit Salomónem ex ea, quæ fuit Uriæ. Sálomon autem génuit Róboam. Róboam autem génuit Abíam. Abías autem génuit Asa. Asa autem génuit Jósaphat. Jósaphat autem génuit Joram. Joram autem génuit Ozíam. Ozías autem génuit Jóatham. Jóatham autem génuit Achaz. Achaz autem génuit Ezechíam. Ezechías autem génuit Manássen. Manásses autem génuit Amon. Amon autem génuit Josíam. Josías autem génuit Jechoníam et fratres ejus in transmigratióne Babylónis. Et post transmigratiónem Babylónis: Jechonías génuit Saláthiel. Saláthiel autem génuit Zoróbabel. Zoróbabel autem génuit Abiud. Abiud autem génuit Elíacim. Elíacim autem génuit Azor. Azor autem génuit Sadoc. Sadoc autem génuit Achim. Achim autem génuit Eliud. Eliud autem génuit Eleázar. Eleázar autem génuit Mathan. Mathan autem génuit Jacob. Jacob autem génuit Joseph, virum Maríæ, de qua natus est Jesus, qui vocátur Christus."}],"Offertorium":[{"k":"text","la":"Beáta es, Virgo María, quæ ómnium portásti Creatórem: genuísti qui te fecit, et in ætérnum pérmanes Virgo."}],"Secreta":[{"k":"text","la":"Unigéniti tui, Dómine, nobis succúrrat humánitas: ut, qui natus de Vírgine, matris integritátem non mínuit, sed sacrávit; in Nativitátis ejus sollémniis, nostris nos piáculis éxuens, oblatiónem nostram tibi fáciat accéptam Jesus Christus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, celebritátis ánnuæ votíva sacraménta: præsta, quǽsumus; ut et temporális vitæ nobis remédia prǽbeant et ætérnæ."},{"k":"macro","name":"Per Dominum"}]},"hr":{"8f0eae79d2d2c5a4":{"t":"Sedulije, Ps 44, 2\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove! (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove!"},"9359156fc0b78272":{"t":"<i>Pomolimo se</i>.\nUdijeli, Gospodine, svojim slugama dar nebeske milosti, da zavjetni blagdan rođenja blažene Djevice dade porast mira onima kojima je njezin porod postao početkom spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"12e5755cdaafa4c3":{"t":"Izr 8, 22-35\nČitanje Knjige Mudrosti: Gospodin me je imao u početku svojih putova, prije nego je išta učinio. Bila sam oduvijek određena, prije postanka zemlje. Još nije bilo bezdana, a ja sam već bila začeta. Izvori voda još nisu bili provreli, planine nisu postojale, rodila sam se prije bregova. Još nije bio stvorio ni Zemlju, ni rijeke, niti postavio zemaljske stožere, a ja sam postojala. Kad je pripremao svod, kad je stalnim zakonom postavljao međaše bezdanima, kad je gore učvršćivao zrak i dolje pokretao izvore voda, kad je unaokolo udarao granice moru i postavljao zakone vodama da se ne prelijevaju izvan svojih korita, kad je stavljao osnove zemlji, bila sam s njime i svime upravljala. Radovala sam se svakog dana, igrala sam pred njim čitavo vrijeme, igrala sam po zemaljskom krugu i užitak mi je biti s ljudima. Zato me, djeco, čujte! Blago onima koji idu mojim putovima. Slušajte nauku, budite mudri, nemojte je odbaciti. Blago čovjeku koji mene sluša i koji svaki dan bdije uz moja vrata i čuva ulaze u moj dom. Tko mene nađe naći će život i primit će spasenje od Gospodina."},"a78ab01cf59234e0":{"t":"Blagoslovljena si i časna, Djevo Marijo, koja si bez povrede djevičanstva bila majka Spasiteljeva. Bogorodice Djevo, u tvojem se zatvori krilu postavši čovjek, onaj koga sav svijet ne može obuhvatiti.\n\nSretna si, sveta Djevo Marijo, i svake si hvale predostojna, jer je iz tebe isteklo Sunce pravde, Krist Bog naš.","v":"∅ → aleluia aleluia; ∅ → aleluia"},"35136cb2edd6737a":{"t":"Mt 1, 1-16\nPočetak svetog Evanđelje po Mateju. Knjiga rođenja Isusa Krista, sina Davidova, sina Abrahamova. Abraham je imao sina Izaka, Izak je imao sina Jakova, Jakov je imao sina Judu i njegovu braću. Juda je imao sina Faresa i Zaru od Tamare, Fares je imao sina Ezrona, Ezron je imao sina Arama, Aram je imao sina Aminadaba, Aminadab je imao sina Nasona, Nason je imao sina Salmona, Salmon je imao sina Boza od Rahabe, Boz je Imao sina Obeda od Rute, Obed je imao sina Jeseja, Jesej je imao sina kralja Davida. Kralj David je imao sina Salamona s bivšom Urijinom ženom. Salamon je imao sina Roboama, Roboam je imao sina Abiju, Abija je imao sina Asu, Asa je imao sina Jozafata, Jozafat je imao sina Joatama, Joatam je imao sina Ahaza, Ahaz je imao sina Ezekiju, Ezekija je imao sina Manasiju, Manasija je imao sina Amona, Amon je imao sina Joziju, Jozija je imao sina Jehoniju i njegovu braću u vrijeme seobe u Babilon. A poslije seobe u Babilon Jehonija je imao sina Salatijela, Salatijel je imao sina Zorobabela, Zorobabel je imao sina Abijuda. Abijud je imao sina Elijacima, Elijacim je imao sina Azora, Azor je imao sina Sadoka, Sadok je imao sina Ahima, Ahim je imao sina Elijuda, Elijud je imao sina Eleazara, Eleazar je imao sina Matana, Matan je imao sina Jakova, Jakov je imao sina Josipa, muža Marijina, od koje se rodio Isus. koji se zove Krist."},"6356ff1e5bf54d76":{"t":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega; porodila si onoga koji te je stvorio i dovijeka ostaješ Djevica. <i>Aleluja</i>.","v":"aleluia → ∅"},"32512c05b736dcdd":{"t":"Pomoglo nam, Gospodine, čovječanstvo tvojega Jedinorođenoga, koji rodivši se od Djevice materinog djevičanstva nije umanjio, nego ga je posvetio; da nas o blagdanu njezina rođenja oslobodi od naših krivica i naš prinos učini tebi prijatnim, Isus Krist, Gospodin naš:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"146d5968599461de":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o rođenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca."},"150f57ef8d5d33a5":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, zavjetna otajstva godišnje svečanosti, molimo te, da nam udijele okrepu i za vremeniti i za vječni život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
